package com.yonlab.vision;
import org.junit.Test;import static org.junit.Assert.*;
/** Discoverable Gradle regressions; host contract driver retains individual assertion evidence. */
public final class OneModelPolicyTest {
 @Test public void modelsAreCompatibleAndNotPerformancePresets(){assertArrayEquals(new String[]{"efficientdet-lite0","ssd-mobilenet-v1","yolox-nano","nanodet-plus","efficientdet-lite1"},OneModelPolicy.models("detect",27));assertArrayEquals(new String[]{"mobilenet-v4-fp32","mobilenet-v2-2022","efficientnet-lite0-f32","efficientnet-lite0-i8","resnet18-v1","squeezenet1-1"},OneModelPolicy.models("classify",27));assertArrayEquals(new String[]{"mlkit-pose","mlkit-pose-accurate","movenet-lightning","movenet-thunder","posenet-mobilenet","blazepose-full"},OneModelPolicy.models("pose",27));assertEquals("ssd-mobilenet-v1",OneModelPolicy.defaultId("flow",27));try{OneModelPolicy.validate("drive","yolo26n",27);fail();}catch(IllegalArgumentException expected){}}
 @Test public void everyPublicSlotHasAUniqueSelectableIdAndAValidDefault(){java.util.Set<String> distinct=new java.util.HashSet<>();int slots=0;for(OneCatalog.Feature feature:OneCatalog.all()){String[] ids=OneModelPolicy.models(feature.id,27);java.util.Set<String> local=new java.util.HashSet<>();for(String id:ids){assertTrue(feature.id+":"+id,local.add(id));assertFalse(id.matches("(?:cpu|threads?)[124]"));OneModelPolicy.validate(feature.id,id,27);distinct.add(id);}slots+=ids.length;if(ids.length>0)assertTrue(local.contains(OneModelPolicy.defaultId(feature.id,27)));}assertEquals(82,slots);assertEquals(63,distinct.size());}
 @Test public void addedWeightsKeepTheApiGateAndLanguageDefaults(){assertArrayEquals(new String[]{"ssd-mobilenet-v1"},OneModelPolicy.models("detect",23));assertEquals("mlkit-ocr-latin",OneModelPolicy.defaultId("ocr",27,"GO"));assertEquals("doc-ocr-ko",OneModelPolicy.defaultId("document",27,"KO"));assertEquals(3,ModelPlusPolicy.added("ocr").length);}
 @Test public void rejectedInt8ConversionCannotBeSelected(){try{OneModelPolicy.validate("classify","mobilenet-v4-int8",27);fail("rejected conversion remained public");}catch(IllegalArgumentException expected){}}
 @Test public void softmaxAndReverseLetterboxAreStable(){float[] probability=OneModelMath.softmax(new float[]{1000,1001});assertEquals(.7310586f,probability[1],.00001f);assertArrayEquals(new float[]{0,0,1,1},OneModelMath.unletterbox(0,140,640,500,1280,720,640),.00001f);try{OneModelMath.softmax(new float[]{Float.NaN});fail();}catch(IllegalArgumentException expected){}}
 @Test public void exportedTextCannotBecomeMarkupOrSpreadsheetFormula(){assertEquals("&lt;img &amp; &quot;x&quot;&gt;",OneModelMath.html("<img & \"x\">"));assertEquals("\"'=SUM(1,2)\"",OneModelMath.csv("=SUM(1,2)"));}
 @Test public void matchingUsesClassAndOneToOneBoxes(){assertArrayEquals(new long[]{1,1,0},OneDetectionEval.evaluate(new float[][]{{0,0,1,1,.9f,0},{0,0,1,1,.8f,0}},new float[][]{{0,0,1,1,0}},.5f));assertArrayEquals(new long[]{0,1,1},OneDetectionEval.evaluate(new float[][]{{0,0,1,1,.9f,1}},new float[][]{{0,0,1,1,0}},.5f));}
}
